package com.example.cryptve.model;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

/**
 * JPA entity that represents a row in the PASSDOC file / table.
 * <p>
 * Original COBOL file record layout (TOTFILE):
 * <pre>
 *   02  FILE-USERID    PIC X(8)
 *   02  FILE-PASS      PIC X(8)
 *   02  FILLER         PIC X(4)
 * </pre>
 * The userId is the natural primary key stored in the sequential file;
 * it is mapped directly as the JPA {@code @Id} here.
 * </p>
 */
@Entity
@Table(name = "passdoc")
public class PassDocument {

    /** FILE-USERID PIC X(8) – unique user identifier, acts as PK. */
    @Id
    @Column(name = "userid", length = 8, nullable = false)
    private String userId;

    /** FILE-PASS PIC X(8) – stored encrypted password. */
    @Column(name = "pass", length = 8, nullable = false)
    private String pass;

    // ----------------------------------------------------------------
    // Constructors
    // ----------------------------------------------------------------

    protected PassDocument() {
        // JPA requirement
    }

    public PassDocument(String userId, String pass) {
        this.userId = userId;
        this.pass   = pass;
    }

    // ----------------------------------------------------------------
    // Accessors
    // ----------------------------------------------------------------

    public String getUserId() {
        return userId;
    }

    public void setUserId(String userId) {
        this.userId = userId;
    }

    public String getPass() {
        return pass;
    }

    public void setPass(String pass) {
        this.pass = pass;
    }
}

