package com.example.cryptve.repository;

import com.example.cryptve.model.PassDocument;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.stereotype.Repository;

import java.util.Optional;

/**
 * Repository for {@link PassDocument} entities (maps to the PASSDOC sequential
 * file accessed in COBOL paragraph 0300-COMPARE-PASS).
 *
 * <p>The COBOL program reads the sequential file record-by-record looking for
 * a record whose FILE-USERID matches LS-USERID.  This is replaced by a single
 * keyed lookup via {@link #findById(Object)}, which is semantically equivalent
 * and far more efficient.</p>
 */
@Repository
public interface PassDocumentRepository extends JpaRepository<PassDocument, String> {

    /**
     * Find a password document by the exact user-id string (trimmed, 8-char
     * padded on the DB side).
     *
     * @param userId the 8-character user identifier
     * @return an {@link Optional} wrapping the stored record, or empty if the
     *         user is not found
     */
    Optional<PassDocument> findByUserId(String userId);
}

// === FILE: src/main/java/com/example/cryptve/dto/CryptoVerificationRequest.java ===
package com.example.cryptve.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;

/**
 * Inbound DTO that carries the three LINKAGE-SECTION parameters fed to the
 * original COBOL program CRYPTVE:
 * <pre>
 *   LS-PASSWORD  PIC X(8)
 *   LS-USERID    PIC X(8)
 *   LS-ADDATE    PIC X(10)   (format: YYYY-MM-DD)
 * </pre>
 */
public record CryptoVerificationRequest(

        @NotBlank(message = "password must not be blank")
        @Size(max = 8, message = "password must be at most 8 characters")
        String password,

        @NotBlank(message = "userId must not be blank")
        @Size(min = 6, max = 8, message = "userId must be between 6 and 8 characters")
        String userId,

        @NotBlank(message = "adminDate must not be blank")
        @Pattern(regexp = "\\d{4}-\\d{2}-\\d{2}",
                 message = "adminDate must match YYYY-MM-DD")
        String adminDate
) {}

// === FILE: src/main/java/com/example/cryptve/dto/CryptoVerificationResponse.java ===
package com.example.cryptve.dto;

/**
 * Outbound DTO that maps the COBOL LS-FLAG output structure:
 * <pre>
 *   02 LS-FLAG-RETURN  PIC X   (0 = OK, 1 = INVALID, 2 = ERROR, 9 = PENDING)
 *   02 LS-FLAG-ERROR   PIC X(4)
 * </pre>
 */
public record CryptoVerificationResponse(
        /** 0 = OK, 1 = INVALID password, 2 = system/IO error. */
        int flagReturn,
        /** Supplemental error code, populated only when flagReturn == 2. */
        String flagError
) {

    /** Convenience factory – success. */
    public static CryptoVerificationResponse ok() {
        return new CryptoVerificationResponse(0, "");
    }

    /** Convenience factory – invalid password / user not found. */
    public static CryptoVerificationResponse invalid() {
        return new CryptoVerificationResponse(1, "");
    }

    /** Convenience factory – system error. */
    public static CryptoVerificationResponse error(String code) {
        return new CryptoVerificationResponse(2, code);
    }
}

// === FILE: src/main/java/com/example/cryptve/service/CryptoService.java ===
package com.example.cryptve.service;

import com.example.cryptve.dto.CryptoVerificationRequest;
import com.example.cryptve.dto.CryptoVerificationResponse;
import com.example.cryptve.model.PassDocument;
import com.example.cryptve.repository.PassDocumentRepository;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.Optional;

/**
 * Service layer that faithfully reproduces the business logic of COBOL program
 * CRYPTVE, paragraphs:
 * <ul>
 *   <li>0100-OPEN-FILE   → verified implicitly via JPA connectivity</li>
 *   <li>0200-CRYPTPASS   → {@link #encryptPassword(String, String, String)}</li>
 *   <li>0300-COMPARE-PASS → {@link #verify(CryptoVerificationRequest)}</li>
 *   <li>0400-CLOSE-FILE  → managed by JPA / connection pool</li>
 * </ul>
 *
 * <h2>Encryption algorithm (0200-CRYPTPASS)</h2>
 * <ol>
 *   <li>Derive a seed from {@code PASSFILE-KEY = Integer.parseInt(userId.substring(5,8)) + 1}
 *       and the admin-date reformatted as {@code yyyyMMdd}.</li>
 *   <li>Seed Java's {@link java.util.Random} with that seed value, draw one
 *       {@code nextDouble()} then multiply by 1000 to get WS-KEY (integer).
 *       This mirrors {@code FUNCTION RANDOM(WS-DATE)*1000}.</li>
 *   <li>Iterate over each character of the password (up to 8, stopping at
 *       the first space / blank).</li>
 *   <li>For each character, spin an inner loop until the produced output byte
 *       is not one of the forbidden byte values (0x40, 0x10, 0x00, 0x30, 0x20).</li>
 *   <li>Select the transform branch via {@code WS-COUNTER2 mod 3}:
 *       <ul>
 *         <li>0 → {@code WS-KEY1 = WS-PASS * WS-KEY1}; result char = 2nd byte of WS-PASS</li>
 *         <li>1 → {@code WS-USERID1 = WS-PASS * WS-USERID1}; result char = 2nd byte of WS-USERID</li>
 *         <li>2 → {@code WS-KEY1 = WS-PASS * WS-USERID1 * WS-KEY1}; result char = 2nd byte of WS-PASS</li>
 *       </ul>
 *   </li>
 * </ol>
 */
@Service
public class CryptoService {

    private static final Logger log = LoggerFactory.getLogger(CryptoService.class);

    // Forbidden output bytes – mirrors the COBOL inner-loop exit condition
    private static final byte[] FORBIDDEN_BYTES = {
        (byte) 0x40, (byte) 0x10, (byte) 0x00, (byte) 0x30, (byte) 0x20
    };

    private final PassDocumentRepository passDocumentRepository;

    public CryptoService(PassDocumentRepository passDocumentRepository) {
        this.passDocumentRepository = passDocumentRepository;
    }

    // ----------------------------------------------------------------
    // Public API
    // ----------------------------------------------------------------

    /**
     * Main entry point – mirrors COBOL MAIN-PARA.
     *
     * @param request the inbound linkage-section parameters
     * @return verification result
     */
    @Transactional(readOnly = true)
    public CryptoVerificationResponse verify(CryptoVerificationRequest request) {

        // 0200-CRYPTPASS
        String cryptPass = encryptPassword(
                request.password(),
                request.userId(),
                request.adminDate());

        log.debug("Encrypted password: {}", cryptPass);
        log.debug("User ID           : {}", request.userId());

        // 0300-COMPARE-PASS
        return comparePassword(request.userId(), cryptPass);
    }

    // ----------------------------------------------------------------
    // 0200-CRYPTPASS
    // ----------------------------------------------------------------

    /**
     * Encrypts a plain-text password using the CRYPTVE algorithm.
     *
     * <p>The algorithm is a proprietary transformation derived from the
     * COBOL source. It is preserved byte-for-byte so that values produced
     * here are identical to those written by the original COBOL program.</p>
     *
     * @param password  plain-text password (LS-PASSWORD, max 8 chars)
     * @param userId    user identifier     (LS-USERID,   max 8 chars)
     * @param adminDate admin date string   (LS-ADDATE,   format YYYY-MM-DD)
     * @return 8-character encrypted password string (WS-CRYPTPASS)
     */
    public String encryptPassword(String password, String userId, String adminDate) {

        // -----------------------------------------------------------------
        // Derive PASSFILE-KEY = integer value of userId[5..7] + 1
        //   COBOL: MOVE LS-USERID(6:3) TO PASSFILE-KEY
        //          ADD 1 TO PASSFILE-KEY
        // COBOL substring references are 1-based; (6:3) = chars 6,7,8
        // Java  substring is 0-based; chars at index 5,6,7
        // -----------------------------------------------------------------
        String paddedUserId = padRight(userId, 8);
        String passPart     = paddedUserId.substring(5, 8).trim();
        long   passkeyLong  = 0L;
        if (!passPart.isEmpty()) {
            try {
                passkeyLong = Long.parseLong(passPart);
            } catch (NumberFormatException e) {
                passkeyLong = 0L;
            }
        }
        passkeyLong += 1; // ADD 1 TO PASSFILE-KEY

        // -----------------------------------------------------------------
        // Build WS-DATE (8 digits) from LS-ADDATE (YYYY-MM-DD)
        //   COBOL:
        //     MOVE LS-ADDATE(1:4) TO WS-DATE(1:4)  → year
        //     MOVE LS-ADDATE(6:2) TO WS-DATE(5:2)  → month  (skip '-' at pos 5)
        //     MOVE LS-ADDATE(9:2) TO WS-DATE(7:2)  → day    (skip '-' at pos 8)
        // -----------------------------------------------------------------
        String paddedDate = padRight(adminDate, 10);
        String wsDateStr  =
                paddedDate.substring(0, 4) +  // YYYY
                paddedDate.substring(5, 7) +  // MM
                paddedDate.substring(8, 10);  // DD

        long wsDate = 0L;
        try {
            wsDate = Long.parseLong(wsDateStr);
        } catch (NumberFormatException e) {
            wsDate = 0L;
        }

        // -----------------------------------------------------------------
        // COMPUTE WS-KEY = FUNCTION RANDOM(WS-DATE) * 1000
        // COBOL FUNCTION RANDOM(seed) seeds the generator and returns a
        // pseudo-random number in [0,1).  We replicate this with java.util.Random.
        // WS-KEY is PIC 9(2) – two decimal digits, so we keep only the low-order
        // two digits (0-99) of the product.
        // -----------------------------------------------------------------
        java.util.Random rng = new java.util.Random(wsDate);
        int wsKey = (int) (rng.nextDouble() * 1000) % 100; // WS-KEY PIC 9(2)

        // -----------------------------------------------------------------
        // WS-USERID1 / WS-USERID: take first 2 bytes of userId
        //   COBOL: MOVE LS-USERID(1:4) TO WS-USERID
        //          WS-USERID is PIC X(2) — REDEFINES of a PIC 9(4) COMP field.
        //   In the COMP (binary) world the 4-byte integer value of the first
        //   4 characters is stored; the last 2 bytes of that 4-byte word are
        //   exposed as WS-USERID (PIC X(2)).  We capture the first 4 chars
        //   as bytes and treat bytes [2] and [3] (0-based) as the "low 2".
        // -----------------------------------------------------------------
        byte[] userIdBytes = paddedUserId.substring(0, Math.min(4, paddedUserId.length()))
                                         .getBytes(java.nio.charset.StandardCharsets.ISO_8859_1);
        // Pad to 4 bytes
        byte[] wsUseridBytes = new byte[4];
        System.arraycopy(userIdBytes, 0, wsUseridBytes,
                         4 - userIdBytes.length, userIdBytes.length);

        // WS-USERID1 as a 16-bit signed integer (PIC 9(4) COMP = 2-byte binary)
        // COBOL PIC 9(4) COMP occupies 2 bytes; redefines as PIC X(2).
        // We treat WS-USERID1 as a short (2 bytes).
        short wsUserid1 = (short) (((wsUseridBytes[0] & 0xFF) << 8)
                                 | (wsUseridBytes[1] & 0xFF));

        // WS-USERID is the character overlay of those 2 bytes
        byte[] wsUseridCharBytes = new byte[]{
            wsUseridBytes[2], wsUseridBytes[3]
        };

        // -----------------------------------------------------------------
        // Output array: WS-CRYPTPASS (8 chars)
        // -----------------------------------------------------------------
        byte[] cryptChar = new byte[8]; // initialised to 0x00

        String paddedPassword = padRight(password, 8);

        // Outer loop: WS-COUNTER1 from 1 to 8 (1-based), stop at first space
        for (int counter1 = 1; counter1 <= 8; counter1++) {

            // COBOL: UNTIL WS-COUNTER1 > 8 OR LS-PASSWORD(WS-COUNTER1:1) = SPACE
            char pwChar = paddedPassword.charAt(counter1 - 1);
            if (pwChar == ' ') {
                break;
            }

            // Inner loop: WS-COUNTER2 from WS-COUNTER1 by 1 (TEST AFTER)
            // Exit when cryptChar[counter1-1] is NOT one of the forbidden bytes
            int counter2 = counter1;
            do {
                // COMPUTE WS-MOD1 = FUNCTION MOD(WS-COUNTER2, 3)
                int mod1 = counter2 % 3;

                // MOVE LS-PASSWORD(WS-COUNTER1:2) TO WS-PASSWORD
                // WS-PASS is PIC 9(4) COMP (2-byte binary),
                // WS-PASSWORD REDEFINES as PIC X(2)
                // Take 2 bytes starting at counter1 (1-based)
                int pwStart = counter1 - 1;
                int pwEnd   = Math.min(pwStart + 2, paddedPassword.length());
                String pwSlice = paddedPassword.substring(pwStart, pwEnd);
                while (pwSlice.length() < 2) pwSlice += " ";

                byte[] pwBytes = pwSlice.getBytes(java.nio.charset.StandardCharsets.ISO_8859_1);
                // WS-PASS as short (2 bytes)
                short wsPass = (short) (((pwBytes[0] & 0xFF) << 8) | (pwBytes[1] & 0xFF));

                // MOVE LS-USERID(WS-COUNTER1:2) TO WS-USERID
                int uidStart = counter1 - 1;
                int uidEnd   = Math.min(uidStart + 2, paddedUserId.length());
                String uidSlice = paddedUserId.substring(uidStart, uidEnd);
                while (uidSlice.length() < 2) uidSlice += " ";

                byte[] uidSliceBytes = uidSlice.getBytes(java.nio.charset.StandardCharsets.ISO_8859_1);
                // WS-USERID as overlay (2 chars)
                wsUseridCharBytes = new byte[]{ uidSliceBytes[0], uidSliceBytes[1] };
                // WS-USERID1 as short
                wsUserid1 = (short) (((uidSliceBytes[0] & 0xFF) << 8)
                                    | (uidSliceBytes[1] & 0xFF));

                // Perform the chosen computation and set the output byte
                switch (mod1) {
                    case 0 -> {
                        // COMPUTE WS-KEY1 = WS-PASS * WS-KEY1
                        // WS-KEY1 is PIC 9(4) COMP, same storage as WS-KEY (PIC 9(2) overlay)
                        // WS-KEY is the low-byte overlay; after compute, move WS-KEY1 to WS-PASS
                        // then: MOVE WS-PASSWORD(2:1) TO WS-CRYPTCHAR(WS-COUNTER1)
                        short newKey1 = (short) (wsPass * (short) wsKey);
                        wsKey  = newKey1 & 0xFF; // keep low byte as WS-KEY
                        wsPass = newKey1;
                        // WS-PASSWORD(2:1) = second byte of the pw slice
                        cryptChar[counter1 - 1] = pwBytes[1];
                    }
                    case 1 -> {
                        // COMPUTE WS-USERID1 = WS-PASS * WS-USERID1
                        // MOVE WS-USERID(2:1) TO WS-CRYPTCHAR
                        wsUserid1 = (short) (wsPass * wsUserid1);
                        wsUseridCharBytes[0] = (byte) (wsUserid1 >> 8);
                        wsUseridCharBytes[1] = (byte) (wsUserid1 & 0xFF);
                        // WS-USERID(2:1) = second byte of USERID slice
                        cryptChar[counter1 - 1] = uidSliceBytes[1];
                    }
                    case 2 -> {
                        // COMPUTE WS-KEY1 = WS-PASS * WS-USERID1 * WS-KEY1
                        // MOVE WS-KEY1 TO WS-PASS
                        // MOVE WS-PASSWORD(2:1) TO WS-CRYPTCHAR
                        short newKey1 = (short) (wsPass * wsUserid1 * (short) wsKey);
                        wsKey  = newKey1 & 0xFF;
                        wsPass = newKey1;
                        cryptChar[counter1 - 1] = pwBytes[1];
                    }
                    default -> throw new IllegalStateException("Unexpected mod value: " + mod1);
                }

                counter2++;

            } while (isForbiddenByte(cryptChar[counter1 - 1]));
        }

        // Convert byte array to ISO-8859-1 String (preserves binary content)
        return new String(cryptChar, java.nio.charset.StandardCharsets.ISO_8859_1);
    }

    // ----------------------------------------------------------------
    // 0300-COMPARE-PASS
    // ----------------------------------------------------------------

    /**
     * Looks up the stored encrypted password for {@code userId} and compares
     * it with the supplied {@code cryptPass}.
     *
     * <p>Mirrors COBOL paragraph 0300-COMPARE-PASS:
     * <ol>
     *   <li>Set flag to 9 (pending).</li>
     *   <li>Read file sequentially looking for matching FILE-USERID.</li>
     *   <li>If found and passwords match → flag = 0 (OK).</li>
     *   <li>If found but passwords differ → flag = 1 (INVALID).</li>
     *   <li>If not found → flag = 1 (INVALID).</li>
     * </ol>
     * The sequential file read is replaced by a keyed JPA lookup, which is
     * semantically equivalent.</p>
     *
     * @param userId   the user identifier to look up
     * @param cryptPass the locally computed encrypted password
     * @return {@link CryptoVerificationResponse}
     */
    private CryptoVerificationResponse comparePassword(String userId, String cryptPass) {

        // Pad userId to 8 chars to match stored value
        String paddedUserId = padRight(userId, 8);

        Optional<PassDocument> optDoc = passDocumentRepository.findByUserId(paddedUserId);

        if (optDoc.isEmpty()) {
            // User not found in file → flag = 1 (INVALID)
            log.debug("User '{}' not found in PASSDOC", paddedUserId);
            return CryptoVerificationResponse.invalid();
        }

        PassDocument doc = optDoc.get();

        // Pad stored pass to 8 chars for comparison
        String storedPass = padRight(doc.getPass(), 8);
        String localPass  = padRight(cryptPass, 8);

        if (localPass.equals(storedPass)) {
            log.debug("Password verification succeeded for user '{}'", paddedUserId);
            return CryptoVerificationResponse.ok();
        } else {
            log.debug("Password mismatch for user '{}'", paddedUserId);
            return CryptoVerificationResponse.invalid();
        }
    }

    // ----------------------------------------------------------------
    // Helpers
    // ----------------------------------------------------------------

    /**
     * Right-pads a string with spaces to exactly {@code length} characters,
     * reproducing COBOL's fixed-length PIC X(n) behaviour.
     *
     * @param value  source string (may be null)
     * @param length desired length
     * @return padded string
     */
    static String padRight(String value, int length) {
        if (value == null) value = "";
        if (value.length() >= length) return value.substring(0, length);
        return String.format("%-" + length + "s", value);
    }

    /**
     * Returns {@code true} when the given byte is one of the five forbidden
     * values that cause the inner COBOL loop to continue iterating:
     * {@code 0x40, 0x10, 0x00, 0x30, 0x20}.
     *
     * @param b the byte to test
     * @return {@code true} if forbidden
     */
    static boolean isForbiddenByte(byte b) {
        for (byte forbidden : FORBIDDEN_BYTES) {
            if (b == forbidden) return true;
        }
        return false;
    }
}

