package com.example.cryptve.controller;

import com.example.cryptve.dto.CryptoVerificationRequest;
import com.example.cryptve.dto.CryptoVerificationResponse;
import com.example.cryptve.service.CryptoService;
import jakarta.validation.Valid;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/**
 * REST controller exposing the CRYPTVE password verification operation.
 *
 * <p>Maps to the original COBOL program CRYPTVE invoked via CICS LINK/XCTL.
 * The LINKAGE-SECTION parameters are received as a JSON request body.</p>
 *
 * <table border="1">
 *   <caption>Return code semantics</caption>
 *   <tr><th>flagReturn</th><th>HTTP status</th><th>Meaning</th></tr>
 *   <tr><td>0</td><td>200</td><td>Password verified OK</td></tr>
 *   <tr><td>1</td><td>401</td><td>Invalid password or user not found</td></tr>
 *   <tr><td>2</td><td>500</td><td>System / data error</td></tr>
 * </table>
 */
@RestController
@RequestMapping("/api/v1/crypto")
public class CryptoController {

    private final CryptoService cryptoService;

    public CryptoController(CryptoService cryptoService) {
        this.cryptoService = cryptoService;
    }

    /**
     * Verifies that the supplied plain-text password, when encrypted with the
     * CRYPTVE algorithm, matches the password stored in PASSDOC for the given
     * user.
     *
     * @param request {@link CryptoVerificationRequest} with password, userId,
     *                and adminDate
     * @return {@link ResponseEntity} containing {@link CryptoVerificationResponse}
     */
    @PostMapping("/verify")
    public ResponseEntity<CryptoVerificationResponse> verify(
            @Valid @RequestBody CryptoVerificationRequest request) {

        CryptoVerificationResponse response = cryptoService.verify(request);

        HttpStatus status = switch (response.flagReturn()) {
            case 0  -> HttpStatus.OK;
            case 1  -> HttpStatus.UNAUTHORIZED;
            default -> HttpStatus.INTERNAL_SERVER_ERROR;
        };

        return ResponseEntity.status(status).body(response);
    }
}

