package com.example.cryptve.config;

import com.example.cryptve.dto.CryptoVerificationResponse;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

import java.util.stream.Collectors;

/**
 * Global exception handler – translates unhandled exceptions into structured
 * {@link CryptoVerificationResponse} payloads, preserving the LS-FLAG semantics
 * defined in the original COBOL LINKAGE SECTION.
 */
@RestControllerAdvice
public class GlobalExceptionHandler {

    private static final Logger log = LoggerFactory.getLogger(GlobalExceptionHandler.class);

    /**
     * Handles bean-validation failures (invalid request body).
     *
     * @param ex the validation exception
     * @return 400 Bad Request with a combined error message
     */
    @ExceptionHandler(MethodArgumentNotValidException.class)
    public ResponseEntity<CryptoVerificationResponse> handleValidation(
            MethodArgumentNotValidException ex) {

        String errors = ex.getBindingResult()
                .getFieldErrors()
                .stream()
                .map(fe -> fe.getField() + ": " + fe.getDefaultMessage())
                .collect(Collectors.joining("; "));

        log.warn("Validation failed: {}", errors);

        // Truncate to 4 chars to match LS-FLAG-ERROR PIC X(4)
        String code = errors.length() > 4 ? errors.substring(0, 4) : errors;
        return ResponseEntity
                .status(HttpStatus.BAD_REQUEST)
                .body(CryptoVerificationResponse.error(code));
    }

    /**
     * Catch-all handler for unexpected runtime exceptions.
     *
     * @param ex the exception
     * @return 500 Internal Server Error with flagReturn = 2
     */
    @ExceptionHandler(Exception.class)
    public ResponseEntity<CryptoVerificationResponse> handleGeneric(Exception ex) {
        log.error("Unexpected error in CRYPTVE service", ex);
        return ResponseEntity
                .status(HttpStatus.INTERNAL_SERVER_ERROR)
                .body(CryptoVerificationResponse.error("E500"));
    }
}
